function grid$hrbsvaora(f){
  this.constructor(f);
}
grid$hrbsvaora.prototype = new DirEvent();
grid$hrbsvaora.prototype.afterInitFields = function(){
  var p = this._dir;
}
grid$hrbsvaora.prototype.beforeInit = function(renderType){
  var p = this._dir, g = p.grid(), dt = new DataTable(g.data.Tables[0]);
  dt.setPrimaryKey(['id', 'ngay']);
  if (p.options.reload == "") {
    var k = p.options.dtUpdate.count();
    while(k--) dt.update(p.options.dtUpdate, k, true); //Chuyen qua lai giua cac trang thi update lai gia tri theo key
  }
}
grid$hrbsvaora.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid(), dt = g.data;
  if (p.options.reload != "") {
    p.options.dtUpdate = dt.clone(null, null); //Neu reload lai store thi tao lai bang thay doi
    p.options.dtUpdate.setPrimaryKey(['id', 'ngay']);
  }
  p.find(".grid-input-field[value!='00:00']").css("font-weight", "700");

}
grid$hrbsvaora.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir, g = p.grid(), dt = g.data;
  switch (c){
    case 'gio_vao1':
    case 'gio_ra1':
    case 'gio_vao2':
    case 'gio_ra2':
    case 'gio_vao3':
    case 'gio_ra3':
    case 'gio_vao4':
    case 'gio_ra4':
      p.options.dtUpdate.update(dt, r, false, [c]);
      o.css("font-weight", (v != '00:00')? "700":"");
      break;
		case 'ma_cong':
			p.options.dtUpdate.update(dt, r, false, [c]);
		console.log(dt)
			o.css("font-weight", (v != '')? "700":"");
			break
		case 'so_gio':
			p.options.dtUpdate.update(dt, r, false, [c]);
			o.css("font-weight", (v != 0)? "700":"");
			break
		case 'ly_do':
			p.options.dtUpdate.update(dt, r, false, [c]);
			break
    default:
      break;
  }

}
grid$hrbsvaora.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
    case 'save':
      if (p.options.dtUpdate.count() == 0) {
        $.showToast(p.msg('noChange'));
        return false;
      }
      var m = new Memvars();
      m.val('bsvaora', 'T', p.options.dtUpdate.sqlval(null, null, ['ma_nv', 'ho_ten_nv', 'ma_bp', 'ma_vtr']), 'hrbsvaora'); //Khai bao field EX de ko request len server cho nhe
      p.request('Save', '', m, function(p, d, run) {
        if (run) p._refresh(true);
      });
      return false;
    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
